INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich einen /48-Präfix in mehrere /64-Präfixe aufteilen?', 2, '[{"text": "Ja", "correct": true, "because": "16 Bits bleiben für Subnetze"}, {"text": "Nein", "correct": false, "because": "Aufteilung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele /64-Subnetze passen in einen /48-Präfix?', 3, '[{"text": "65.536", "correct": true, "because": "2^(64-48) = 2^16"}, {"text": "256", "correct": false, "because": "Zu niedrig, 2^8"}, {"text": "16", "correct": false, "because": "Zu niedrig, 2^4"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bits nutze ich, um von /48 zu /64 zu kommen?', 4, '[{"text": "16 Bits", "correct": true, "because": "64 - 48 = 16"}, {"text": "8 Bits", "correct": false, "because": "Zu wenig für /64"}, {"text": "32 Bits", "correct": false, "because": "Zu viel, überschreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /48 zu /64 erhöht die Subnetzanzahl. b) Interface-ID bleibt 64 Bits.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) mehr Subnetze, b) Standard"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Aufteilung von /48 zu /64?', 5, '[{"text": "Hostanzahl pro Subnetz", "correct": true, "because": "Fokus auf Subnetze"}, {"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Anzahl"}, {"text": "Netzwerkanteil", "correct": false, "because": "Kern der Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein /48-Präfix mehr als 1000 /64-Subnetze erlaubt?', 2, '[{"text": "Ja", "correct": true, "because": "2^16 = 65.536"}, {"text": "Nein", "correct": false, "because": "Weit mehr als 1000"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits leihe ich, um von /48 zu /64 zu gehen?', 3, '[{"text": "16", "correct": true, "because": "64 - 48 = 16"}, {"text": "12", "correct": false, "because": "Falsche Differenz"}, {"text": "8", "correct": false, "because": "Zu wenig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren bestimmen die Aufteilung von /48 zu /64?', 5, '[{"text": "Geliehene Bits", "correct": true, "because": "16 Bits für Subnetze"}, {"text": "Präfixdifferenz", "correct": true, "because": "48 zu 64"}, {"text": "Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /48 zu /64 nutzt 16 Bits. b) Es verkleinert die Interface-ID. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Interface-ID bleibt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Aufteilung von /48 zu /64?', 4, '[{"text": "Präfixdifferenz", "correct": false, "because": "Definiert Subnetze"}, {"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Anzahl"}, {"text": "Übertragungsrate", "correct": true, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ergeben 10 geliehene Bits von /48 genau 1024 /58-Subnetze?', 2, '[{"text": "Ja", "correct": true, "because": "2^10 = 1024"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte ändern sich bei der Aufteilung von /48 zu /64?', 4, '[{"text": "Subnetzanzahl", "correct": true, "because": "2^16 Subnetze"}, {"text": "Netzwerkbits", "correct": true, "because": "48 zu 64"}, {"text": "Interface-ID", "correct": false, "because": "Bleibt 64 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass /48 zu /64 nur 256 Subnetze erlaubt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "2^16 = 65.536"}, {"text": "Ja", "correct": false, "because": "Zu niedrig, 2^8"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Aufteilung von /48 zu /64?', 3, '[{"text": "Subnetzanzahl", "correct": true, "because": "Ziel der Aufteilung"}, {"text": "Hostanzahl", "correct": false, "because": "Sekundär"}, {"text": "Kürzeste Adresse", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /48 zu /64 nutzt 16 Bits. b) Es ist für SLAAC nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse erwartest du bei der Aufteilung?', 5, '[{"text": "/48 zu /64 = 65.536 Subnetze", "correct": true, "because": "2^16"}, {"text": "/48 zu /56 = 256 Subnetze", "correct": true, "because": "2^8"}, {"text": "/48 zu /64 = 16 Subnetze", "correct": false, "because": "Zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Präfixaufteilung unwichtig?', 3, '[{"text": "Geliehene Bits", "correct": false, "because": "Bestimmen Anzahl"}, {"text": "Präfixlänge", "correct": false, "because": "Definiert Subnetze"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind 12 Bits von /48 zu /60 möglich?', 2, '[{"text": "Ja", "correct": true, "because": "60 - 48 = 12"}, {"text": "Nein", "correct": false, "because": "Formel passt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /48 zu /64 die Interface-ID verändert?', 3, '[{"text": "Nein", "correct": true, "because": "Bleibt 64 Bits"}, {"text": "Ja", "correct": false, "because": "Nur Netzwerkbits ändern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitanzahl wähle ich, um von /48 zu /64 65.536 Subnetze zu bekommen?', 4, '[{"text": "16", "correct": true, "because": "2^16 = 65.536"}, {"text": "8", "correct": false, "because": "2^8 = 256"}, {"text": "10", "correct": false, "because": "2^10 = 1024"}]');
